ALTER TABLE order_requests DROP CONSTRAINT order_requests_state_check;
ALTER TABLE order_requests ADD CONSTRAINT order_requests_state_check CHECK(state IN ('draft','checking_availability','reserved','awaiting_payment','confirmed','preparing','ready_for_dispatch','out_for_delivery','delivered','unavailable','cancelled','delivery_failed','returned','refunded'));
ALTER TABLE order_requests ADD COLUMN financial_hold boolean NOT NULL DEFAULT false;
ALTER TABLE order_requests ADD COLUMN availability_deadline timestamptz;
ALTER TABLE order_requests ADD COLUMN reminder_sent boolean NOT NULL DEFAULT false;
ALTER TABLE order_requests ADD COLUMN escalated_at timestamptz;
ALTER TABLE order_events ADD COLUMN notified_at timestamptz;
CREATE TABLE operation_audit(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),subject_id uuid,action text NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE uploads(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN ('product','document','proof')),payload text NOT NULL,bytes integer NOT NULL CHECK(bytes>0 AND bytes<=5242880),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX uploads_owner_idx ON uploads(owner_id);
CREATE TABLE vendor_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),private_details text NOT NULL,document_id uuid NOT NULL REFERENCES uploads(id),window_start timestamptz NOT NULL,window_end timestamptz NOT NULL,version integer NOT NULL DEFAULT 0,CHECK(window_end>window_start));
CREATE TABLE delivery_zones(id uuid PRIMARY KEY,name text NOT NULL,state text NOT NULL,city text NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 0);
CREATE TABLE order_deliveries(order_id uuid PRIMARY KEY REFERENCES order_requests(id),zone_id uuid NOT NULL REFERENCES delivery_zones(id),private_details text NOT NULL,delivery_date date NOT NULL,assigned_to uuid REFERENCES users(id),proof_id uuid REFERENCES uploads(id),tracking_reference text,attempts integer NOT NULL DEFAULT 0);
CREATE TABLE order_remedies(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES order_requests(id),kind text NOT NULL CHECK(kind IN ('cancellation','return')),status text NOT NULL CHECK(status IN ('requested','approved','rejected','closed')),reason text NOT NULL,refund_limit_kobo bigint NOT NULL DEFAULT 0,review_note text,reviewed_by uuid REFERENCES users(id),received_back boolean NOT NULL DEFAULT false,restock_quantity integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_corrections(id uuid PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payment_records(id),request_id uuid NOT NULL UNIQUE,delta_kobo bigint NOT NULL,corrected_kobo bigint NOT NULL CHECK(corrected_kobo>=0),actor_id uuid NOT NULL REFERENCES users(id),note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_cases(id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES users(id),order_id uuid REFERENCES order_requests(id),request_id uuid NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','waiting_customer','resolved')),subject text NOT NULL,version integer NOT NULL DEFAULT 0,assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(customer_id,request_id));
CREATE TABLE support_messages(id uuid PRIMARY KEY,case_id uuid NOT NULL REFERENCES support_cases(id),author_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,internal boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),dedupe_key text NOT NULL,title text NOT NULL,message text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,dedupe_key));
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at);
ALTER TABLE email_outbox ADD COLUMN next_attempt_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE worker_health(name text PRIMARY KEY,last_started timestamptz,last_succeeded timestamptz,last_failed timestamptz,lease_until timestamptz);
ALTER TABLE worker_health ADD COLUMN lease_token uuid;
